#!/bin/bash
# Gazebo field acceptance: drive every tunnel in both directions.
#
#   tools/nav_regress/run_tunnel_accept.sh [tunnel_accept.py args...]
#   OUT=/tmp/nav_m3c tools/nav_regress/run_tunnel_accept.sh --order pair
#
# Goals are generated by tunnel_accept.py (map frame) and handed to run_nav.sh as an array:
# passing them as a command substitution on the command line breaks when the list spans lines.
# With staging (default) a crossing is two goals: the open spot beyond the near mouth, then the open
# spot beyond the far one - 24 goals for 12 crossings.
# Afterwards, tools/nav_regress/tunnel_stats.py reads $OUT/truth.log (gz ground truth) and reports the
# in-body lateral / heading error per crossing; those are the acceptance criteria (<= 3 cm, <= 3 deg).
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
OUT=${OUT:-/tmp/nav_m3c}
mkdir -p "$OUT"

python3 "$HERE/tunnel_accept.py" "$@" --manifest "$OUT/tunnel_manifest.json" > "$OUT/requested_goals.txt" || exit $?
mapfile -t GOALS < "$OUT/requested_goals.txt"
if [ "${#GOALS[@]}" -eq 0 ]; then echo 'tunnel_accept.py produced no goals'; exit 1; fi
echo "goals (map frame): ${#GOALS[@]}"
printf '  %s\n' "${GOALS[@]}"

rc=0
GOAL_FRAME=map OUT="$OUT" bash "$HERE/run_nav.sh" "${GOALS[@]}" || rc=$?
python3 "$HERE/tunnel_stats.py" --out "$OUT" --manifest "$OUT/tunnel_manifest.json" || rc=1
exit "$rc"
